export const meta = {
  name: 'roadmap-investigation',
  description: 'Investigate every remaining roadmap issue and produce an ordered execution plan',
  phases: [
    { title: 'Investigate', detail: 'one agent per remaining roadmap area' },
    { title: 'Synthesise', detail: 'order the slices and surface conflicts' },
  ],
}

const AREAS = [
  { key: '73', prompt: 'GitHub issue #73 (P2.1 Introduce a durable travel domain model)' },
  { key: '74', prompt: 'GitHub issue #74 (P2.2 Add inventory holds)' },
  { key: '75', prompt: 'GitHub issue #75 (P2.3 Integrate real payments safely). DECISION ALREADY MADE BY THE USER: use a Stripe sandbox, mocked for now — do not integrate a live Stripe account or require real credentials. Plan around a mocked/sandboxed Stripe boundary.' },
  { key: '76', prompt: 'GitHub issue #76 (P2.4 Implement cancellation, disruption, and refund rules)' },
  { key: '77', prompt: 'GitHub issue #77 (P2.5 Implement check-in and travel documents)' },
  { key: '78', prompt: 'GitHub issue #78 (P3.1 Repair travel-guide presentation). DECISION ALREADY MADE BY THE USER: redesign it so it works, rather than minimally repairing. NOTE: the page currently has severe overlapping text at desktop width — city names overlap descriptions and reviews overlap each other. This is pre-existing and verified against main.' },
  { key: '79', prompt: 'GitHub issue #79 (P3.2 Add responsive layouts)' },
  { key: '80', prompt: 'GitHub issue #80 (P3.3 Complete the accessibility pass). KNOWN FACT: app/globals.css sets no :focus or :focus-visible style anywhere, so most controls have no visible focus indicator; only .search-degraded button and the checkout leg tabs bring their own. Verify this and scope it.' },
  { key: '81', prompt: 'GitHub issue #81 (P3.4 Standardize feedback and media)' },
  { key: '82', prompt: 'GitHub issue #82 (P3.5 Make guides and notifications production-ready)' },
  { key: 'phase4', prompt: 'GitHub issues #83, #84, #85, #86 (Phase 4: reconcile schedules and future flights; make time and status accurate; staff permissions and audit history; customer-support workflows). Cover all four.' },
  { key: 'phase5', prompt: 'GitHub issues #87, #88, #89, #90 (Phase 5: observability; harden deployment and database operations; application and privacy controls; expand continuous verification). Cover all four.' },
  { key: 'debt', prompt: 'GitHub issues #135 (drop flight/schedule price strings), #137 (drop Passenger.seatNumber/cabinClass/flightId), #131 (multicity itineraries — USER DECISION: multicity here means CONNECTING itineraries, not customer-chosen stopovers), #130 (reward redemption), #105 (airport dataset), #95, #96, #97, #98 (tooling). Cover all of them, briefly for the small ones.' },
]

const PLAN_SCHEMA = {
  type: 'object',
  required: ['area', 'summary', 'slices', 'blockers', 'defectsFound'],
  properties: {
    area: { type: 'string' },
    summary: { type: 'string', description: 'What state this area is actually in today, based on reading the code — not restating the issue' },
    slices: {
      type: 'array',
      description: 'Ordered, independently shippable slices. Each must be small enough for one reviewable PR.',
      items: {
        type: 'object',
        required: ['title', 'whatChanges', 'filesAffected', 'risk', 'estimate'],
        properties: {
          title: { type: 'string' },
          whatChanges: { type: 'string' },
          filesAffected: { type: 'array', items: { type: 'string' } },
          risk: { type: 'string', enum: ['low', 'medium', 'high'] },
          estimate: { type: 'string', enum: ['small', 'medium', 'large'] },
          needsMigration: { type: 'boolean' },
          needsUserDecision: { type: 'string', description: 'Empty if none. Otherwise the precise question.' },
        },
      },
    },
    blockers: { type: 'array', items: { type: 'string' }, description: 'Prerequisites in other issues, by number' },
    defectsFound: {
      type: 'array',
      description: 'Live defects discovered while reading, that are not what the issue asked about',
      items: {
        type: 'object',
        required: ['title', 'evidence', 'severity'],
        properties: {
          title: { type: 'string' },
          evidence: { type: 'string', description: 'File and line, and why it is wrong' },
          severity: { type: 'string', enum: ['low', 'medium', 'high'] },
        },
      },
    },
  },
}

phase('Investigate')

const plans = await parallel(AREAS.map(area => () => agent(
  `You are investigating one area of a Next.js 16 / Prisma / PostgreSQL flight booking app so that another engineer can execute it.

Repository root is the current working directory. Read AGENTS.md first — it governs how work is done here (thin vertical slices, TDD, hand-authored SQL migrations, expand/migrate/contract for schema changes).

Your area: ${area.prompt}

Run \`gh issue view <number>\` to read the issue text. Then READ THE ACTUAL CODE to determine what state the area is really in. Do not restate the issue. Recent work has already landed a lot: round trips are fully modelled as ItineraryLeg sequences, seats are per leg in SeatAssignment, fares are stored in minor units as priceCents, cabin class is wired through search and checkout, and the product identity is consolidated in lib/brand.ts. Several roadmap items may be partly or wholly done already — say so if they are.

Produce:
- summary: what is actually true today, from the code
- slices: ordered, independently shippable pieces. Each must be one reviewable PR. Be concrete about files.
- blockers: other issue numbers that must land first
- defectsFound: live bugs you notice while reading that the issue did not ask about. Only include ones you can point at a file and line for and explain. Do not speculate.

Be rigorous and specific. Vague plans are worthless. If something is already done, say it is done rather than inventing work.`,
  { label: `area:${area.key}`, phase: 'Investigate', schema: PLAN_SCHEMA }
)))

phase('Synthesise')

const usable = plans.filter(Boolean)
log(`${usable.length} of ${AREAS.length} areas investigated`)

const synthesis = await agent(
  `You are ordering the remaining work on a flight booking app into an execution plan.

Here are per-area investigation reports as JSON:

${JSON.stringify(usable, null, 2)}

Produce a single ordered execution plan. Rules:
- Respect declared blockers strictly.
- Prefer slices that remove ambiguity or correctness hazards early (schema contract steps, anything where two sources of truth exist).
- Group anything that touches the same migration timeline so migrations do not collide.
- Call out explicitly any slice that still needs a user decision, and what the question is.
- Call out every defect found across all areas, deduplicated, most severe first.
- Be honest about total scale: state roughly how many PRs this is, and which parts are genuinely large features rather than fixes.

Return prose, not JSON. Be concise and specific. This will be read by an engineer deciding what to do next.`,
  { label: 'synthesise', phase: 'Synthesise' }
)

return synthesis

